import json,glob,os,collections,sys
root=os.path.expanduser('~/.claude/projects')
F=('input_tokens','output_tokens','cache_read_input_tokens','cache_creation_input_tokens')
enums=collections.Counter(); hits=collections.Counter()
for sid in sys.argv[1:]:
    main=glob.glob(os.path.join(root,'*',sid+'.jsonl'))[0]
    sub=os.path.join(main[:-6],'subagents')
    ids={}; 
    for m in glob.glob(os.path.join(sub,'*.meta.json')):
        aid=os.path.basename(m)[6:-10]; tu=json.load(open(m)).get('toolUseId')
        ids[aid]=aid; ids[tu]=aid
    per={}
    for p in glob.glob(os.path.join(sub,'agent-*.jsonl')):
        aid=os.path.basename(p)[6:-6]; last={}; ts=[]
        with open(p,'rb') as fh:
            for line in fh:
                try:o=json.loads(line)
                except: continue
                if o.get('timestamp'): ts.append(o['timestamp'])
                if o.get('type')!='assistant': continue
                m=o.get('message') or {}; u=m.get('usage')
                if u and m.get('id') and m.get('model')!='<synthetic>': last[m['id']]=({k:int(u.get(k) or 0) for k in F},o.get('timestamp'))
        cum=collections.Counter()
        for u,_ in last.values():
            for k in F: cum[k]+=u[k]
        fin=max(last.values(),key=lambda x:x[1])[0] if last else {}
        per[aid]=(cum,fin)
    out=[]
    with open(main,'rb') as fh:
        for line in fh:
            try:o=json.loads(line)
            except: continue
            a=o.get('attachment')
            if not(isinstance(a,dict) and a.get('type')=='queued_command' and isinstance(a.get('usage'),dict)): continue
            org=a.get('origin') or {}; enums[(org.get('kind'),org.get('producer'))]+=1
            aid=None
            for f in ('runId','reminderId','delivery_id','source_uuid'):
                v=a.get(f)
                if v in ids: hits[f]+=1; aid=ids[v]
            # also the outer line fields
            for f in ('toolUseID','sourceToolUseID','parentToolUseID'):
                v=o.get(f)
                if v in ids: hits['line.'+f]+=1; aid=ids[v]
            if aid and aid in per:
                cum,fin=per[aid]; u=a['usage']
                out.append((u['totalTokens'],sum(cum.values()),sum(fin.values()),fin.get('output_tokens'),cum['output_tokens']))
    print(sid[:8],'matched',len(out))
    for r in out[:8]: print('  notif',r[0],'| cum',r[1],'| last-msg ctx',r[2],'| last out',r[3],'| cum out',r[4])
print('enums',enums.most_common()); print('id hits',hits.most_common())
EOF
